draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // One
  ctx.beginPath();
  ctx.rect(W/4, H/4, 20, H/2);
  ctx.stroke();

  // One
  ctx.beginPath();
  ctx.rect(W/2, H/4, 20, H/2);
  ctx.stroke();

  // Two
  ctx.beginPath();
  ctx.rect(W/4 + 50 + Math.sin(t)*20, H/4, 30, H/2);
  ctx.stroke();

  // Five
  ctx.beginPath();
  ctx.arc(W/2 + 50 + Math.cos(t)*20, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
